#!/usr/bin/env bash
# Question 15: Name resolution broken. Generated by Quick Create; variables arrive as environment variables.
set -euo pipefail

kubectl create namespace "${Q15_NS}" >/dev/null 2>&1 || kubectl get namespace "${Q15_NS}" >/dev/null
timeout 60 bash -c "until kubectl -n '${Q15_NS}' get serviceaccount default >/dev/null 2>&1; do sleep 1; done"
kubectl apply -f - <<EOF
apiVersion: apps/v1
kind: Deployment
metadata:
  name: web
  namespace: ${Q15_NS}
spec:
  replicas: 1
  selector:
    matchLabels: { app: web }
  template:
    metadata:
      labels: { app: web }
    spec:
      containers:
        - name: web
          image: nginx:1.27-alpine
          ports: [{ containerPort: 80 }]
---
apiVersion: v1
kind: Service
metadata:
  name: web
  namespace: ${Q15_NS}
spec:
  selector: { app: web }
  ports: [{ port: 80 }]
EOF
kubectl -n "${Q15_NS}" delete pod "${Q15_CLIENT}" --ignore-not-found --wait=true >/dev/null
kubectl -n "${Q15_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"'"${Q15_CLIENT}"'"},"spec":{"containers":[{"name":"shell","image":"busybox:1.36","command":["sleep","infinity"]}]}}'
if ! kubectl -n "${Q15_NS}" wait --for=condition=Ready "pod/${Q15_CLIENT}" --timeout=180s; then
  kubectl -n "${Q15_NS}" describe "pod/${Q15_CLIENT}" >&2 || true
  exit 1
fi
kubectl -n "${Q15_NS}" rollout status deployment/web --timeout=180s

case "${Q15_FAULT}" in
  corefile-typo)
    kubectl -n kube-system get configmap coredns -o yaml | sed -E 's#^([[:space:]]*)forward \. /etc/resolv\.conf#\1forwrd . /etc/resolv.conf#' | kubectl replace -f - >/dev/null
    kubectl -n kube-system get configmap coredns -o jsonpath='{.data.Corefile}' | grep -qE -- 'forwrd \. ' || { echo "could not edit the Corefile" >&2; exit 1; }
    kubectl -n kube-system delete pod -l k8s-app=kube-dns --wait=false >/dev/null
    ;;
  scaled-to-zero)
    kubectl -n kube-system scale deployment/coredns --replicas=0
    kubectl -n kube-system wait --for=delete pod -l k8s-app=kube-dns --timeout=120s >/dev/null || true
    ;;
  cluster-domain)
    kubectl -n kube-system get configmap coredns -o yaml | sed -E 's#kubernetes cluster\.local #kubernetes cluster.lab #' | kubectl replace -f - >/dev/null
    kubectl -n kube-system get configmap coredns -o jsonpath='{.data.Corefile}' | grep -qE -- 'kubernetes cluster\.lab ' || { echo "could not edit the Corefile" >&2; exit 1; }
    kubectl -n kube-system rollout restart deployment/coredns
    kubectl -n kube-system rollout status deployment/coredns --timeout=240s
    ;;
  kube-dns-selector)
    kubectl -n kube-system patch service kube-dns -p '{"spec":{"selector":{"k8s-app":"kube-dns-v2"}}}'
    ;;
  client-dns-policy)
    kubectl -n "${Q15_NS}" delete pod "${Q15_CLIENT}" --ignore-not-found --wait=true >/dev/null
    kubectl -n "${Q15_NS}" apply -f - <<< '{"apiVersion":"v1","kind":"Pod","metadata":{"name":"'"${Q15_CLIENT}"'"},"spec":{"dnsPolicy":"Default","containers":[{"name":"shell","image":"busybox:1.36","command":["sleep","infinity"]}]}}'
    if ! kubectl -n "${Q15_NS}" wait --for=condition=Ready "pod/${Q15_CLIENT}" --timeout=180s; then
      kubectl -n "${Q15_NS}" describe "pod/${Q15_CLIENT}" >&2 || true
      exit 1
    fi
    ;;
  corefile-loop)
    kubectl -n kube-system get configmap coredns -o yaml | sed -E 's#^([[:space:]]*)forward \. /etc/resolv\.conf#\1forward . 127.0.0.1#' | kubectl replace -f - >/dev/null
    kubectl -n kube-system get configmap coredns -o jsonpath='{.data.Corefile}' | grep -qE -- 'forward \. 127\.0\.0\.1' || { echo "could not edit the Corefile" >&2; exit 1; }
    kubectl -n kube-system delete pod -l k8s-app=kube-dns --wait=false >/dev/null
    ;;
  coredns-rbac)
    kubectl get clusterrolebinding system:coredns -o json > "/var/tmp/cka-q15.crb.json"
    kubectl delete clusterrolebinding system:coredns >/dev/null
    kubectl -n kube-system delete pod -l k8s-app=kube-dns --wait=false >/dev/null
    ;;
  kube-dns-target-port)
    kubectl -n kube-system get service kube-dns -o yaml | sed -E 's/targetPort: 53$/targetPort: 5353/' | kubectl replace -f - >/dev/null
    [ "$(kubectl -n kube-system get service kube-dns -o jsonpath='{.spec.ports[*].targetPort}' | tr ' ' '\n' | grep -cx 5353)" = 2 ] || { echo "could not edit Service kube-dns" >&2; exit 1; }
    ;;
  corefile-key)
    kubectl -n kube-system get configmap coredns -o yaml | sed -E 's/^  Corefile: /  corefile: /' | kubectl replace -f - >/dev/null
    kubectl -n kube-system get configmap coredns -o jsonpath='{.data.corefile}' | grep -q kubernetes || { echo "could not rename the Corefile key" >&2; exit 1; }
    kubectl -n kube-system delete pod -l k8s-app=kube-dns --wait=false >/dev/null
    ;;
  coredns-image)
    kubectl -n kube-system get deployment coredns -o jsonpath='{.spec.strategy}' > "/var/tmp/cka-q15.strategy"
    kubectl -n kube-system patch deployment coredns --type=merge -p '{"spec":{"strategy":{"type":"RollingUpdate","rollingUpdate":{"maxUnavailable":"100%","maxSurge":0}}}}' >/dev/null
    img="$(kubectl -n kube-system get deployment coredns -o jsonpath='{.spec.template.spec.containers[0].image}')"
    echo "$img" > "/var/tmp/cka-q15.image"
    kubectl -n kube-system set image deployment/coredns coredns="$(sed -E 's/:[^:/]+$/:v0.0.0/' <<< "$img")" >/dev/null
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pods -l k8s-app=kube-dns -o jsonpath='{range .items[*]}{.status.containerStatuses[0].ready}{"\n"}{end}' | grep -c true)" == 0 ]] && break
      sleep 2
    done
    ;;
  coredns-config-volume)
    kubectl -n kube-system get deployment coredns -o jsonpath='{.spec.strategy}' > "/var/tmp/cka-q15.strategy"
    kubectl -n kube-system patch deployment coredns --type=merge -p '{"spec":{"strategy":{"type":"RollingUpdate","rollingUpdate":{"maxUnavailable":"100%","maxSurge":0}}}}' >/dev/null
    kubectl -n kube-system patch deployment coredns --type=json -p '[{"op":"replace","path":"/spec/template/spec/volumes/0/configMap/name","value":"coredns-custom"}]' >/dev/null
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pods -l k8s-app=kube-dns -o jsonpath='{range .items[*]}{.status.containerStatuses[0].ready}{"\n"}{end}' | grep -c true)" == 0 ]] && break
      sleep 2
    done
    ;;
  coredns-memory-limit)
    kubectl -n kube-system get deployment coredns -o jsonpath='{.spec.strategy}' > "/var/tmp/cka-q15.strategy"
    kubectl -n kube-system patch deployment coredns --type=merge -p '{"spec":{"strategy":{"type":"RollingUpdate","rollingUpdate":{"maxUnavailable":"100%","maxSurge":0}}}}' >/dev/null
    kubectl -n kube-system set resources deployment/coredns -c coredns --limits=memory=8Mi --requests=memory=8Mi >/dev/null
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pods -l k8s-app=kube-dns -o jsonpath='{range .items[*]}{.status.containerStatuses[0].ready}{"\n"}{end}' | grep -c true)" == 0 ]] && break
      sleep 2
    done
    ;;
  coredns-hosts-plugin)
    kubectl -n kube-system get configmap coredns -o jsonpath='{.data.Corefile}' > /tmp/cka-Corefile
    python3 -c 'import sys; from pathlib import Path; t=Path("/tmp/cka-Corefile").read_text(); n="kubernetes cluster.local"; i="hosts {\n        127.0.0.1 web." + sys.argv[1] + ".svc.cluster.local web.svc.cluster.local web.cluster.local web\n        fallthrough\n    }\n    "; Path("/tmp/cka-Corefile").write_text(t.replace(n, i+n, 1) if "hosts {" not in t else t)' "${Q15_NS}"
    grep -q "127.0.0.1 web.${Q15_NS}.svc.cluster.local" /tmp/cka-Corefile || { echo "could not inject hosts plugin" >&2; exit 1; }
    kubectl -n kube-system create configmap coredns --from-file=Corefile=/tmp/cka-Corefile -o yaml --dry-run=client | kubectl -n kube-system apply -f - >/dev/null
    kubectl -n kube-system delete pod -l k8s-app=kube-dns --wait=false >/dev/null
    ;;
  coredns-ready-port)
    kubectl -n kube-system get deployment coredns -o jsonpath='{.spec.strategy}' > "/var/tmp/cka-q15.strategy"
    kubectl -n kube-system patch deployment coredns --type=merge -p '{"spec":{"strategy":{"type":"RollingUpdate","rollingUpdate":{"maxUnavailable":"100%","maxSurge":0}}}}' >/dev/null
    kubectl -n kube-system patch deployment coredns --type=json -p '[{"op":"replace","path":"/spec/template/spec/containers/0/readinessProbe/httpGet/port","value":8182}]' >/dev/null
    for _ in $(seq 1 60); do
      [[ "$(kubectl -n kube-system get pods -l k8s-app=kube-dns -o jsonpath='{range .items[*]}{.status.containerStatuses[0].ready}{"\n"}{end}' | grep -c true)" == 0 ]] && break
      sleep 2
    done
    ;;
  *)
    echo "unknown fault" >&2
    exit 1
    ;;
esac

# The question only makes sense if the client really cannot resolve the name.
for _ in $(seq 1 60); do
  kubectl -n "${Q15_NS}" exec "${Q15_CLIENT}" -- wget -qO- -T 3 http://web 2>/dev/null | grep -q nginx || exit 0
  sleep 3
done
echo "the client still resolves web" >&2
exit 1
